CREATE TABLE IF NOT EXISTS platform_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS platform_banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(140) NOT NULL, subtitle VARCHAR(255) NOT NULL DEFAULT '', image_path VARCHAR(255) NOT NULL DEFAULT '', target_path VARCHAR(255) NOT NULL DEFAULT '/cassino', position VARCHAR(24) NOT NULL DEFAULT 'home', enabled TINYINT(1) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 100, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS platform_promotions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(140) NOT NULL, description TEXT NOT NULL, image_path VARCHAR(255) NOT NULL DEFAULT '', starts_at DATETIME NULL, ends_at DATETIME NULL, enabled TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS affiliate_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(32) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS affiliate_visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, affiliate_id BIGINT UNSIGNED NOT NULL, visitor_hash CHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), INDEX idx_affiliate_visits (affiliate_id,created_at), CONSTRAINT fk_affiliate_visit_link FOREIGN KEY (affiliate_id) REFERENCES affiliate_links(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
